atomic-lost-update.content:
public class Main {

    public static void main(String[] args) throws Exception {
        var barrier=new java.util.concurrent.CyclicBarrier(2);var count=new java.util.concurrent.atomic.AtomicInteger();Runnable job=()->{int before=count.get();try{barrier.await();}catch(Exception e){throw new RuntimeException(e);}count.incrementAndGet();};Thread a=new Thread(job), b=new Thread(job);a.start();b.start();a.join();b.join();System.out.println(count.get());
    }
}

